```c
#include <stdio.h>
#include <string.h>

int L, C;
int candidate[36];
int matchRight[36];
int visited[36];

int dfs(int u) {
    int r = u / C;
    int c = u % C;
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    for (int k = 0; k < 4; k++) {
        int nr = r + dr[k];
        int nc = c + dc[k];

        if (nr < 0 || nr >= L || nc < 0 || nc >= C) {
            continue;
        }

        int v = nr * C + nc;
        if (!candidate[v] || visited[v]) {
            continue;
        }

        visited[v] = 1;
        if (matchRight[v] == -1 || dfs(matchRight[v])) {
            matchRight[v] = u;
            return 1;
        }
    }

    return 0;
}

int main(void) {
    int black[6][6] = {{0}};
    int P;

    if (scanf("%d %d", &L, &C) != 2) {
        return 0;
    }
    scanf("%d", &P);

    for (int i = 0; i < P; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        black[x - 1][y - 1] = 1;
    }

    int count = 0;
    for (int r = 0; r < L; r++) {
        for (int c = 0; c < C; c++) {
            if (black[r][c]) {
                continue;
            }

            int adjacentToBlack = 0;
            if (r > 0 && black[r - 1][c]) adjacentToBlack = 1;
            if (r + 1 < L && black[r + 1][c]) adjacentToBlack = 1;
            if (c > 0 && black[r][c - 1]) adjacentToBlack = 1;
            if (c + 1 < C && black[r][c + 1]) adjacentToBlack = 1;

            if (adjacentToBlack) {
                candidate[r * C + c] = 1;
                count++;
            }
        }
    }

    memset(matchRight, -1, sizeof(matchRight));
    int matching = 0;

    for (int u = 0; u < L * C; u++) {
        int r = u / C;
        int c = u % C;

        if (candidate[u] && (r + c) % 2 == 0) {
            memset(visited, 0, sizeof(visited));
            matching += dfs(u);
        }
    }

    printf("%d\n", count - matching);
    return 0;
}
```

